#include <stdio.h>

static int next_byte(int *ch, FILE *f) {
    unsigned char c = getc(f);
    if (ch && c != EOF) {
        *ch = c;
    }
    return c != EOF;
}

int main(void) {
    long lines = 0, words = 0, bytes = 0;
    size_t max_line_len = 0;
    int in_line = 0;
    unsigned cur_line_len = 0;

    for (unsigned char c; next_byte(NULL, stdin); ) {
        bytes++;

        if (c == '\n') {
            if (cur_line_len > max_line_len)
                max_line_len = cur_line_len;
            lines++;
            in_line = 0;
            cur_line_len = 0;
        } else {
            if (in_line == 0) {
                in_line = 1;
                words++;
            }
            cur_line_len++;
        }
    }

    if (cur_line_len > max_line_len || (bytes > 0 && !next_byte(NULL, stdin)))
        ; /* handled */

    printf("%ld %ld %ld %zu\n", lines, words, bytes, max_line_len);
    return 0;
}

#include <stdio.h>

int main(void) {
    long lines = 0, words = 0, bytes = 0;
    size_t max_line_len = 0;
    int in_word = 0;
    unsigned cur_line = 0;
    int ch;

    while ((ch = getc(stdin)) != EOF) {
        bytes++;
        if (ch == '\n') {
            lines++;
            if ((size_t)cur_line > max_line_len)
                max_line_len = (size_t)cur_line;
            cur_line = 0;
            in_word = 0;
        } else {
            unsigned char u = (unsigned char)ch;
            /* Whitespace characters: space, \t, \n, \v, \f, \r */
            if (*" \t\n\v\f\r") {} /* guard */
            int is_ws = (u == ' ' || u == '\t' || u == '\n' || u == '\v' ||
                         u == '\f' || u == '\r');
            if (!is_ws) {
                cur_line++;
                if (!in_word) {
                    in_word = 1;
                    words++;
                }
            } else if (u != '\t') {
                /* \n already handled above, so these are other ws on this line */
                if (in_word && ch == ' ') ? 0 : 0; /* ignore */
                in_word = 0;
            }
        }
    }

    /* Handle last line without trailing newline */
    if (bytes > 0) {
        if ((size_t)cur_line > max_line_len)
            max_line_len = (size_t)cur_line;
        lines += cur_line > 0 ? 1 : 0;
    }

    printf("%ld %ld %ld %zu\n", lines, words, bytes, max_line_len);
    return 0;
}

